(7761885, 1286012, 129512, '<td valign="top">Title got a chuckle out of me.</td>', 'Title got a chuckle out of me.', '2024-01-08 09:56:37.000000', NULL, 1),
(7761921, 1286016, 42733, '<td valign="top">My favorite in this challenge. The reason, I suspect, not a creature was stirring.</td>', 'My favorite in this challenge. The reason, I suspect, not a creature was stirring.', '2024-01-08 17:01:29.000000', NULL, 1),
(7761922, 1286022, 42733, '<td valign="top">My pick for red in this challenge.</td>', 'My pick for red in this challenge.', '2024-01-08 17:01:40.000000', NULL, 1),
(7761923, 1286005, 42733, '<td valign="top">My pick for yellow in this challenge.</td>', 'My pick for yellow in this challenge.', '2024-01-08 17:01:51.000000', NULL, 1),
(7761924, 1286013, 42733, '<td valign="top">Very nice. The lighting really works for this theme.</td>', 'Very nice. The lighting really works for this theme.', '2024-01-08 17:02:07.000000', NULL, 1),
(7762008, 1286016, 124815, '<td valign="top">I have a visiting black cat quite often, probably younger than Moriarty, a tuxedo one, immensely playful and powerful. I find myself in an impossible position to photograph her like you. <br/>Here the composition is masterly but I''ve no idea what gear you used, what light, what ISO. Granted, I am very lazy when it comes to use any type of lights and have almost none. But I am a poor photographer, at least form the technical point of view.<br/>I marked this with 8 for now although it is best in the show on a par with another one. Perhaps I''d like to see more of his left ear, or his sly look ...but kudos for the composition and its implication</td>', 'I have a visiting black cat quite often, probably younger than Moriarty, a tuxedo one, immensely playful and powerful. I find myself in an impossible position to photograph her like you. Here the composition is masterly but I''ve no idea what gear you used, what light, what ISO. Granted, I am very lazy when it comes to use any type of lights and have almost none. But I am a poor photographer, at least form the technical point of view.I marked this with 8 for now although it is best in the show on a par with another one. Perhaps I''d like to see more of his left ear, or his sly look ...but kudos for the composition and its implication', '2024-01-10 12:33:48.000000', NULL, 1),
(7762009, 1286021, 124815, '<td valign="top">The nice bend of the tree is telling the story. Beautiful</td>', 'The nice bend of the tree is telling the story. Beautiful', '2024-01-10 12:35:13.000000', NULL, 1),
